function rangoTallasDe(p) {
  const t = String((p && p.tallas) || '').trim();
  if (!t) return '';
  const m = t.match(/^(\d{2})\s*[-a]\s*(?:la\s*)?(\d{2})$/i);
  if (m) return m[1] + ' a la ' + m[2];
  const nums = t.split(/[^0-9]+/).filter(Boolean);
  if (!nums.length) return '';
