function mencionaMarcaCatalogo(t) {
  const pal = {};
  for (const w of normTxtG(t).split(/[^a-z0-9]+/)) if (w) pal[w] = true;
  for (const p of catalogo) {
    for (const tk of normMarca(p.marca).split(/[^a-z0-9]+/)) {
      if (tk && tk.length >= 3 && pal[tk]) return true;
